<?php $images=product_images($product);$variantProduct=has_variants($product)&&variants_ready(); ?>
<section class="section product-detail" <?= $variantProduct?'data-variant-product data-variant-config="'.e(json_encode(variant_public($product))).'" data-starting-price="'.e('From '.money(product_price($product))).'"':'' ?>><div class="breadcrumbs"><a href="/shop">Shop</a><span>/</span><a href="/shop?category=<?= e($product['category_slug']??'') ?>"><?= e($product['category_name']??'Accessories') ?></a><span>/</span><?= e($product['name']) ?></div><div class="product-detail-grid"><div><img class="main-product-image" id="product-main-image" src="<?= e(image_url($images[0]??'/assets/favicon.svg')) ?>" alt="<?= e($product['name']) ?>" width="900" height="1000"><div class="thumbnails" data-variant-gallery><?php foreach($images as $image): ?><button data-image="<?= e(image_url($image)) ?>" aria-label="View another image of <?= e($product['name']) ?>"><img src="<?= e(image_url($image)) ?>" alt="" loading="lazy"></button><?php endforeach ?></div><p class="muted" data-variant-image-note role="status"></p></div><div class="product-info"><span class="eyebrow"><?= e($product['category_name']??'Accessories') ?></span><h1><?= e($product['name']) ?></h1><div class="detail-price" data-variant-price><?= $variantProduct?'From ':'' ?><?= money(product_price($product)) ?> <?php if(!$variantProduct&&product_price($product)<(int)$product['price']): ?><del><?= money((int)$product['price']) ?></del><?php endif ?></div><p><?= e($product['short_description']) ?></p><?php foreach(offer_product_conditions($product) as $terms): ?><p class="offer-terms"><?= e($terms) ?> Applied in your bag when conditions are met.</p><?php endforeach ?><?php require ROOT.'/app/views/variants-product.php'; ?><p class="stock" data-variant-stock><?= $product['stock']?(int)$product['stock'].' available':'Currently sold out' ?></p><label class="quantity-label">Quantity<input type="number" id="product-quantity" min="1" max="<?= min(99,(int)$product['stock']) ?>" value="1" <?= $variantProduct||!$product['stock']?'disabled':'' ?>></label><div class="product-buttons"><button class="button" data-add="<?= e($product['id']) ?>" data-quantity="#product-quantity" <?= $variantProduct?'data-needs-variant':'' ?> <?= $variantProduct||!$product['stock']?'disabled':'' ?>>Add to bag</button><button class="button outline" data-add="<?= e($product['id']) ?>" data-quantity="#product-quantity" <?= $variantProduct?'data-needs-variant':'' ?> data-buy <?= $variantProduct||!$product['stock']?'disabled':'' ?>>Buy now</button></div><div class="product-description"><h2>The details</h2><?= paragraphs($product['description']) ?></div><details><summary>Delivery & returns</summary><p><?= e(settings('store')['delivery_description']) ?></p><a class="text-link" href="/delivery-returns">View our policy</a></details><details><summary>Reviews</summary><?php $pr=rows("SELECT * FROM reviews WHERE product_id=? AND status='approved' ORDER BY created_at DESC",[$product['id']]);foreach($pr as $r): ?><blockquote><span class="stars"><?= str_repeat('★',(int)$r['rating']) ?></span><p><?= e($r['comment']) ?></p><cite><?= e($r['name']) ?></cite></blockquote><?php endforeach ?><?php if(!$pr): ?><p>Be the first to share a little love for this piece.</p><?php endif ?><a class="text-link" href="/reviews?product=<?= e($product['id']) ?>">Write a review</a></details></div></div><div class="section-heading"><h2>A little more to love</h2></div><div class="product-grid"><?php $related=array_slice(array_filter(products(['category'=>$product['category_slug']??'']),fn($p)=>$p['id']!==$product['id']),0,4);foreach($related as $p)require ROOT.'/app/views/product-card.php'; ?></div></section>
